CREATE DATABASE IF NOT EXISTS smart_recipe CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_recipe;
CREATE TABLE IF NOT EXISTS recipes (id INT PRIMARY KEY,title VARCHAR(120) NOT NULL,description VARCHAR(300) NOT NULL,emoji VARCHAR(12) NOT NULL,color VARCHAR(10) NOT NULL,minutes INT NOT NULL,servings INT NOT NULL,diet VARCHAR(30) NOT NULL,steps JSON NOT NULL);
CREATE TABLE IF NOT EXISTS ingredients (id INT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS recipe_ingredients (id INT AUTO_INCREMENT PRIMARY KEY,recipe_id INT NOT NULL,ingredient_id INT NOT NULL,quantity VARCHAR(100) NOT NULL,UNIQUE KEY unique_item(recipe_id,ingredient_id),FOREIGN KEY(recipe_id) REFERENCES recipes(id) ON DELETE CASCADE,FOREIGN KEY(ingredient_id) REFERENCES ingredients(id));
CREATE TABLE IF NOT EXISTS favorites (id INT AUTO_INCREMENT PRIMARY KEY,visitor_key VARCHAR(64) NOT NULL,recipe_id INT NOT NULL,UNIQUE KEY favorite_pair(visitor_key,recipe_id),FOREIGN KEY(recipe_id) REFERENCES recipes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reviews (id INT AUTO_INCREMENT PRIMARY KEY,recipe_id INT NOT NULL,visitor_key VARCHAR(64) NOT NULL,display_name VARCHAR(80) NOT NULL,rating TINYINT NOT NULL,comment TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY review_pair(recipe_id,visitor_key),FOREIGN KEY(recipe_id) REFERENCES recipes(id) ON DELETE CASCADE);
